attribute.add:
dataLayer.push({
                    event: 'add_to_cart',
                    ecommerce: {
                      currency      : '#{website.currency_id.name}',
                      value         : #{product._get_combination_info(only_template=True, add_qty=add_qty)['price']},
                      items: [
                      {
                        item_id       : '#{product.default_code if product.default_code else product.name.replace('\'', '\\\'')}',
                        item_name    : '#{product.name.replace('\'', '\\\'')}',
                        discount      :  #{round(product._get_combination_info(only_template=True, add_qty=add_qty)['list_price']-product._get_combination_info(only_template=True, add_qty=add_qty)['price'],2)},
                        item_category : '#{category.name if category else ''}',
                        price         : #{product._get_combination_info(only_template=True, add_qty=add_qty)['list_price']},
                        quantity      : 1
                      }]
                      }});

dataLayer.push({
                              'event': 'select_item',
                              'ecommerce': {
                                'items': [
                                {
                                  'item_id': '#{product.default_code if product.default_code else product.name.replace('\'', '\\\'')}',
                                  'item_name': '#{product.name.replace('\'', '\\\'')}',
                                  'currency': '#{website.currency_id.name}',
                                  'item_category': '#{category.name if category else ''}',
                                  'price':#{product._get_combination_info(only_template=True, add_qty=add_qty)['price']},
                                  'quantity':1,
                                }
                                ]
                              }
                            }
                      );

dataLayer.push({
                              'event': 'select_item',
